1	import AVFoundation
2	import MediaPlayer
3	
4	final class VolumeButtonHandler: ObservableObject {
5	    var onSingleDown: (() -> Void)?
6	    var onDoubleDown: (() -> Void)?
7	    var onSpeechBegan: (() -> Void)?
8	    var onSpeechEnded: (() -> Void)?
9	
10	    // Added to window hierarchy in start() for HUD suppression + slider access
11	    let volumeView = MPVolumeView(frame: CGRect(x: -2000, y: -2000, width: 1, height: 1))
12	
13	    private var observation: NSKeyValueObservation?
14	    // Only read/written on main thread
15	    private var isAdjustingVolume = false
16	
17	    private var lastDownTime: Date?
18	    private var pendingSingleTimer: Timer?
19	
20	    private var speechActive = false
21	    private var speechReleaseTimer: Timer?
22	
23	    private var volumeSlider: UISlider? {
24	        volumeView.subviews.compactMap { $0 as? UISlider }.first
25	    }
26	
27	    func start() {
28	        // Must be in the window hierarchy for slider subview to exist and for HUD suppression
29	        DispatchQueue.main.async { [weak self] in
30	            guard let self else { return }
31	            if let window = UIApplication.shared.connectedScenes
32	                .compactMap({ $0 as? UIWindowScene })
33	                .flatMap({ $0.windows })
34	                .first(where: { $0.isKeyWindow }) {
35	                window.addSubview(self.volumeView)
36	            }
37	
38	            let session = AVAudioSession.sharedInstance()
39	            try? session.setActive(true)
40	
41	            // Allow MPVolumeView to populate its slider subview before use
42	            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
43	                self?.setVolume(0.5)
44	                self?.startObserving(session: session)
45	            }
46	        }
47	    }
48	
49	    func stop() {
50	        observation?.invalidate()
51	        observation = nil
52	        pendingSingleTimer?.invalidate()
53	        speechReleaseTimer?.invalidate()
54	        volumeView.removeFromSuperview()
55	    }
56	
57	    // MARK: - Private
58	
59	    private func startObserving(session: AVAudioSession) {
60	        observation = session.observe(\.outputVolume, options: [.new, .old]) { [weak self] _, change in
61	            guard let self,
62	                  let newVal = change.newValue,
63	                  let oldVal = change.oldValue else { return }
64	
65	            let delta = newVal - oldVal
66	            guard abs(delta) > 0.01 else { return }
67	
68	            // Move all logic to main thread so isAdjustingVolume is safe
69	            DispatchQueue.main.async { [weak self] in
70	                guard let self, !self.isAdjustingVolume else { return }
71	                if delta < 0 {
72	                    self.handleVolumeDown()
73	                } else {
74	                    self.handleVolumeUp()
75	                }
76	                self.setVolume(0.5)
77	            }
78	        }
79	    }
80	
81	    private func handleVolumeDown() {
82	        let now = Date()
83	        if let last = lastDownTime, now.timeIntervalSince(last) < 0.3 {
84	            pendingSingleTimer?.invalidate()
85	            pendingSingleTimer = nil
86	            lastDownTime = nil
87	            onDoubleDown?()
88	        } else {
89	            lastDownTime = now
90	            pendingSingleTimer?.invalidate()
